// Vitreo - Windows Runtime Engine for macOS ARM64
//
// The captured prefix/loop replay harnesses and the global-scope regressions
// that follow them. Split from test_jit_linear.cpp; shared fixtures and
// matchers live in jit_linear_fixture.hpp.

#include "jit_linear_fixture.hpp"

using namespace vitreo;
using namespace vitreo::cpu;
using namespace vitreo::cpu::jit;
using namespace vitreo::cpu::jit::test;

// Local capture input is generated by tools/perf/extract_sampled_prefixes.py.
// This measures initialized-state prefixes, not whole guest functions.
TEST_F(JitLinear64Test, DISABLED_CapturedPrefixReplay) {
    const char* path = std::getenv("VITREO_PREFIX_REPLAY");
    ASSERT_NE(path, nullptr);
    std::ifstream input(path);
    ASSERT_TRUE(input.good());
    std::string name, hex;
    u64 samples = 0, zero_mask = 0;
    usize rows = 0;
    while (input >> name >> samples >> zero_mask >> hex) {
        SCOPED_TRACE(name);
        const GuestAddr replay_addr = kCode64 + rows * 0x200;
        ASSERT_EQ(hex.size() % 2, 0u);
        std::vector<u8> code;
        for (usize i = 0; i < hex.size(); i += 2) {
            code.push_back(static_cast<u8>(std::stoul(hex.substr(i, 2), nullptr, 16)));
        }
        ASSERT_FALSE(code.empty());
        ASSERT_TRUE(m_memory->write_bytes(replay_addr, code.data(), code.size()));
        ASSERT_LT(code.size(), 0x200u);
        ASSERT_LT(rows, 32u);
        auto block = build64(code);
        block.start_addr = replay_addr;
        ASSERT_EQ(block.byte_length, code.size());
        auto* compiled = m_jit->compile(block);
        ASSERT_NE(compiled, nullptr);
        ASSERT_EQ(compiled->guest_size, code.size());
        std::array<u8, 0x4000> seed{};
        for (usize i = 0; i < seed.size(); i += sizeof(GuestAddr)) {
            const GuestAddr pointer = kData64;
            std::memcpy(seed.data() + i, &pointer, sizeof(pointer));
        }
        auto initial = cpu64(kData64);
        initial.rip = replay_addr;
        for (u8 r = 0; r < 16; ++r) {
            initial.gpr.set64(r, (zero_mask & (u64{1} << r)) ? 0 : kData64);
        }
        initial.gpr.set64(ESP, kData64 + 0x3008);
        ASSERT_TRUE(m_memory->write_bytes(kData64, seed.data(), seed.size()));
        auto reference = initial;
        Interpreter interp(reference, *m_memory);
        for (u32 i = 0; i < block.instruction_count; ++i) {
            ASSERT_EQ(interp.step(), ExecResult::Continue);
        }
        reference.materialize_lazy_flags();
        std::array<u8, 0x4000> expected{};
        ASSERT_TRUE(m_memory->read_bytes(kData64, expected.data(), expected.size()));
        ASSERT_TRUE(m_memory->write_bytes(kData64, seed.data(), seed.size()));
        auto actual = initial;
        ASSERT_EQ(test::execute_like_dispatcher(*m_jit, *compiled, actual), JitExecResult::Continue);
        ASSERT_FALSE(actual.pending_raise.active);
        actual.materialize_lazy_flags();
        ASSERT_EQ(actual.rip, replay_addr + code.size());
        for (u8 r = 0; r < 16; ++r) EXPECT_EQ(actual.gpr.get64(r), reference.gpr.get64(r));
        for (usize r = 0; r < 16; ++r) {
            for (usize i = 0; i < 16; ++i) {
                EXPECT_EQ(actual.sse.xmm[r].u8_[i], reference.sse.xmm[r].u8_[i]);
            }
        }
        EXPECT_EQ(actual.flags.cf(), reference.flags.cf());
        EXPECT_EQ(actual.flags.pf(), reference.flags.pf());
        EXPECT_EQ(actual.flags.zf(), reference.flags.zf());
        EXPECT_EQ(actual.flags.sf(), reference.flags.sf());
        EXPECT_EQ(actual.flags.of(), reference.flags.of());
        std::array<u8, 0x4000> got{};
        ASSERT_TRUE(m_memory->read_bytes(kData64, got.data(), got.size()));
        ASSERT_EQ(got, expected);
        ASSERT_FALSE(HasFailure());

        // Reset only bytes changed by this deterministic prefix. The reset
        // and CpuState copy are measured separately; raw time includes both.
        std::vector<usize> changed;
        for (usize i = 0; i < seed.size(); ++i) {
            if (seed[i] != expected[i]) changed.push_back(i);
        }
        auto* host = m_memory->get_region_info_cached(kData64).host_ptr;
        ASSERT_NE(host, nullptr);
        constexpr int iterations = 200000;
        bool valid = true;
        auto measure = [&](bool execute) {
            const auto start = std::chrono::steady_clock::now();
            for (int i = 0; i < iterations; ++i) {
                for (const usize offset : changed) host[offset] = seed[offset];
                actual = initial;
                asm volatile("" : : "r"(&actual) : "memory");
                if (execute) {
                    valid &= test::execute_like_dispatcher(*m_jit, *compiled, actual) == JitExecResult::Continue &&
                             !actual.pending_raise.active && actual.rip == replay_addr + code.size();
                }
            }
            return std::chrono::duration<double, std::nano>(
                std::chrono::steady_clock::now() - start).count() / iterations;
        };
        const double reset_ns = measure(false);
        const double raw_ns = measure(true);
        EXPECT_TRUE(valid);
        std::printf("PREFIX_REPLAY guest=%s samples=%llu instructions=%u native_bytes=%u raw_ns=%.3f reset_ns=%.3f net_ns=%.3f iterations=%d\n",
                    name.c_str(), static_cast<unsigned long long>(samples),
                    block.instruction_count, compiled->code_size, raw_ns, reset_ns,
                    raw_ns - reset_ns, iterations);
        ++rows;
    }
    EXPECT_GT(rows, 0u);
}


TEST_F(JitLinear64Test, WideConstantsPreserveValueAndFlags) {
    // Arm MOVZ/MOVN/MOVK (D2.106-108) only write their destination.
    // Sweep every arrangement of zero, all-one and mixed 16-bit lanes.
    const std::array<u16, 3> lanes{0, 0xffff, 0x8123};
    usize index = 0;
    for (u16 a : lanes) for (u16 b : lanes)
    for (u16 c : lanes) for (u16 d : lanes) {
        const u64 value = u64{a} | (u64{b} << 16) | (u64{c} << 32) | (u64{d} << 48);
        SCOPED_TRACE(value);
        // movabs rax,imm64; mov [rbx],rax
        std::vector<u8> code{0x48, 0xb8};
        for (unsigned shift = 0; shift < 64; shift += 8)
            code.push_back(static_cast<u8>(value >> shift));
        code.insert(code.end(), {0x48, 0x89, 0x03});
        const GuestAddr address = kCode64 + index++ * 0x20;
        ASSERT_TRUE(m_memory->write_bytes(address, code.data(), code.size()));
        auto block = build64(code);
        block.start_addr = address;
        auto* compiled = m_jit->compile(block);
        ASSERT_NE(compiled, nullptr);
        for (const u64 flags : {u64{0x202}, u64{0xad7}}) {
            auto cpu = cpu64(kData64);
            cpu.rip = address;
            cpu.gpr.rax = ~value;
            cpu.flags.rflags = flags;
            EXPECT_EQ(test::execute_like_dispatcher(*m_jit, *compiled, cpu), JitExecResult::Continue);
            EXPECT_FALSE(cpu.pending_raise.active);
            EXPECT_EQ(cpu.gpr.rax, value);
            EXPECT_EQ(m_memory->read_u64(kData64).value(), value);
            cpu.materialize_lazy_flags();
            EXPECT_EQ(cpu.flags.rflags, flags);
            EXPECT_EQ(cpu.rip, address + code.size());
        }
    }
}

TEST_F(JitLinear64Test, DISABLED_CapturedLoopReplay) {
    const char* path = std::getenv("VITREO_LOOP_REPLAY");
    ASSERT_NE(path, nullptr);
    std::ifstream input(path);
    ASSERT_TRUE(input.good());
    struct RestoreLinks {
        bool previous = JitCompiler::jit_link_enabled();
        ~RestoreLinks() {
            if (previous) JitCompiler::enable_jit_link();
            else JitCompiler::disable_jit_link();
        }
    } restore;
    std::string kind, guest, hex, split;
    u64 samples = 0;
    usize row = 0;
    while (input >> kind >> guest >> samples >> hex >> split) {
        ASSERT_TRUE(kind == "fill" || kind == "scan");
        ASSERT_LT(row, 3u);
        SCOPED_TRACE(guest);
        std::vector<u8> code;
        ASSERT_EQ(hex.size() % 2, 0u);
        for (usize i = 0; i < hex.size(); i += 2)
            code.push_back(static_cast<u8>(std::stoul(hex.substr(i, 2), nullptr, 16)));
        ASSERT_LT(code.size(), 0x400u);
        std::vector<usize> cuts;
        std::istringstream parts(split);
        std::string part;
        while (std::getline(parts, part, ',')) cuts.push_back(std::stoul(part));
        ASSERT_GE(cuts.size(), 2u);
        ASSERT_EQ(cuts.front(), 0u);
        ASSERT_EQ(cuts.back(), code.size());
        for (usize i = 1; i < cuts.size(); ++i) ASSERT_GT(cuts[i], cuts[i-1]);
        for (const int mode : {0, 1, 2}) {
            const bool linked = mode != 0;
            const bool trace = mode == 2;
            const std::vector<usize> block_cuts = trace ? std::vector<usize>{0, code.size()} : cuts;
            SCOPED_TRACE(mode);
            if (linked) JitCompiler::enable_jit_link();
            else JitCompiler::disable_jit_link();
            const GuestAddr address = kCode64 + row * 0x1000 + mode * 0x400;
            const GuestAddr end = address + code.size();
            ASSERT_TRUE(m_memory->write_bytes(address, code.data(), code.size()));
            std::vector<CompiledBlock> compiled;
            for (usize i = 1; i < block_cuts.size(); ++i) {
                std::vector<u8> bytes(code.begin() + block_cuts[i-1], code.begin() + block_cuts[i]);
                auto block = build64(bytes);
                block.start_addr = address + block_cuts[i-1];
                ASSERT_EQ(block.byte_length, bytes.size());
                auto* cached = m_cache->insert(block);
                auto* native = m_jit->compile(*cached);
                ASSERT_NE(native, nullptr);
                m_jit->publish_compiled_block(*cached, *native);
                compiled.push_back(*native);
                if (const char* dump = std::getenv("VITREO_LOOP_NATIVE_DUMP")) {
                    std::ofstream output(std::string(dump) + "-" + kind + "-" +
                                         std::to_string(mode) + "-" + std::to_string(i) + ".bin",
                                         std::ios::binary);
                    output.write(reinterpret_cast<const char*>(native->code), native->code_size);
                    ASSERT_TRUE(output.good());
                }
            }
            constexpr u64 count = 128;
            for (const int match : {-1, 0, 127}) {
                if (kind == "fill" && match != -1) continue;
                SCOPED_TRACE(match);
                std::array<u8, 0x4000> seed{};
                for (usize i = 0; i < seed.size() / sizeof(u64); ++i) {
                    const u64 value = i + 1;
                    std::memcpy(seed.data() + i * sizeof(value), &value, sizeof(value));
                }
                auto initial = cpu64(kData64);
                initial.rip = address;
                initial.gpr.rax = kind == "fill" ? kData64 : 0;
                initial.gpr.rcx = count;
                initial.gpr.rdx = count;
                initial.gpr.set64(9, kData64);
                initial.gpr.set64(11, match < 0 ? ~u64{0} : static_cast<u64>(match + 1));
                ASSERT_TRUE(m_memory->write_bytes(kData64, seed.data(), seed.size()));
                auto reference = initial;
                Interpreter interpreter(reference, *m_memory);
                usize steps = 0;
                while (reference.rip != end && steps < 4096) {
                    const auto result = interpreter.step();
                    ASSERT_TRUE(result == ExecResult::Continue || result == ExecResult::Branch);
                    ++steps;
                }
                ASSERT_EQ(reference.rip, end);
                reference.materialize_lazy_flags();
                std::array<u8, 0x4000> expected{}, got{};
                ASSERT_TRUE(m_memory->read_bytes(kData64, expected.data(), expected.size()));
                ASSERT_TRUE(m_memory->write_bytes(kData64, seed.data(), seed.size()));
                auto actual = initial;
                auto run = [&](u64& dispatches) {
                    while (actual.rip != end && dispatches < 2048) {
                        auto it = std::find_if(compiled.begin(), compiled.end(), [&](const auto& b) {
                            return b.guest_addr == actual.rip;
                        });
                        if (it == compiled.end()) return false;
                        ++dispatches;
                        if (test::execute_like_dispatcher(*m_jit, *it, actual) != JitExecResult::Continue ||
                            actual.pending_raise.active) return false;
                    }
                    return actual.rip == end;
                };
                u64 dispatches = 0;
                ASSERT_TRUE(run(dispatches));
                actual.materialize_lazy_flags();
                for (u8 r = 0; r < 16; ++r) EXPECT_EQ(actual.gpr.get64(r), reference.gpr.get64(r));
                EXPECT_EQ(actual.flags.cf(), reference.flags.cf());
                EXPECT_EQ(actual.flags.pf(), reference.flags.pf());
                EXPECT_EQ(actual.flags.zf(), reference.flags.zf());
                EXPECT_EQ(actual.flags.sf(), reference.flags.sf());
                EXPECT_EQ(actual.flags.of(), reference.flags.of());
                ASSERT_TRUE(m_memory->read_bytes(kData64, got.data(), got.size()));
                ASSERT_EQ(got, expected);
                ASSERT_FALSE(HasFailure());
                const char* repetitions = std::getenv("VITREO_LOOP_ITERATIONS");
                const int iterations = repetitions ? std::stoi(repetitions) : 5000;
                ASSERT_GE(iterations, 5000);
                ASSERT_LE(iterations, 1000000);
                u64 total_dispatches = 0;
                bool valid = true;
                const auto start = std::chrono::steady_clock::now();
                for (int i = 0; i < iterations; ++i) {
                    actual = initial;
                    u64 calls = 0;
                    valid &= run(calls);
                    total_dispatches += calls;
                    for (u8 r = 0; r < 16; ++r)
                        valid &= actual.gpr.get64(r) == reference.gpr.get64(r);
                }
                const double ns = std::chrono::duration<double, std::nano>(
                    std::chrono::steady_clock::now() - start).count() / iterations;
                EXPECT_TRUE(valid);
                std::printf("LOOP_REPLAY case=%s guest=%s linked=%d trace=%d match=%d elements=%llu steps=%zu blocks=%zu dispatches_per_run=%.3f ns_per_run=%.3f iterations=%d\n",
                            kind.c_str(), guest.c_str(), linked, trace, match,
                            static_cast<unsigned long long>(count), steps, compiled.size(),
                            static_cast<double>(total_dispatches) / iterations, ns, iterations);
            }
        }
        ++row;
    }
    EXPECT_GT(row, 0u);
}

TEST_F(JitLinear64Test, ScalarStoreOperandsSurviveColdRipPublication) {
    // Intel SDM MOV: the exact source is written, flags are unchanged. A NOP
    // puts every store after block entry so the cold path must publish RIP.
    // Mixed 4 KiB permissions force the helper on the 16 KiB host page.
    struct Form { std::vector<u8> bytes; u64 value; usize width; };
    const std::vector<Form> forms{
        {{0xc6, 0x03, 0x5a}, 0x5a, 1},
        {{0x66, 0xc7, 0x03, 0x34, 0x12}, 0x1234, 2},
        {{0xc7, 0x03, 0x78, 0x56, 0x34, 0x12}, 0x12345678, 4},
        {{0x48, 0xc7, 0x03, 0x78, 0x56, 0x34, 0x92}, 0xffffffff92345678, 8},
    };
    usize index = 0;
    for (const auto& form : forms) for (unsigned stores : {1u, 2u}) {
        std::vector<u8> code{0x90};
        for (unsigned i = 0; i < stores; ++i)
            code.insert(code.end(), form.bytes.begin(), form.bytes.end());
        auto block = build64(code);
        block.start_addr = kCode64 + index++ * 0x100;
        ASSERT_TRUE(m_memory->write_bytes(block.start_addr, code.data(), code.size()));
        auto* compiled = m_jit->compile(block);
        ASSERT_NE(compiled, nullptr);
        for (bool mixed : {false, true}) {
            ASSERT_TRUE(m_memory->protect_region(kData64 + 0x1000, 0x1000,
                mixed ? MemoryProtection::Read : MemoryProtection::ReadWrite));
            const GuestAddr target = kData64 + 0x2004;
            std::array<u8, 16> bytes{}, expected{};
            bytes.fill(0xa5);
            expected = bytes;
            std::memcpy(expected.data(), &form.value, form.width);
            ASSERT_TRUE(m_memory->write_bytes(target, bytes.data(), bytes.size()));
            auto cpu = cpu64(target);
            cpu.rip = block.start_addr;
            cpu.flags.rflags = 0xad7;
            ASSERT_EQ(test::execute_like_dispatcher(*m_jit, *compiled, cpu), JitExecResult::Continue);
            ASSERT_FALSE(cpu.pending_raise.active);
            ASSERT_EQ(cpu.rip, block.start_addr + code.size());
            ASSERT_TRUE(m_memory->read_bytes(target, bytes.data(), bytes.size()));
            EXPECT_EQ(bytes, expected);
            cpu.materialize_lazy_flags();
            EXPECT_EQ(cpu.flags.rflags, 0xad7u);
        }
    }
}
